package com.cardcombat;
import java.util.*;import org.bukkit.*;import org.bukkit.command.*;import org.bukkit.entity.Player;
public final class ShopCommand implements CommandExecutor,TabCompleter{private final CardCombatPlugin p;public ShopCommand(CardCombatPlugin p){this.p=p;}public boolean onCommand(CommandSender s,Command c,String l,String[]a){if(!(s instanceof Player))return true;Player x=(Player)s;if(a.length==0||a[0].equalsIgnoreCase("list")){x.sendMessage(ChatColor.GOLD+"=== Card Shop ===");String cls=p.profiles().getClass(x);for(CardDefinition d:p.cards().all())if(d.cardClass.equalsIgnoreCase(cls)&&p.economy().price(d)>0&&!p.economy().owns(x,d.id))x.sendMessage(ChatColor.YELLOW+d.id+ChatColor.GRAY+" — "+d.name+ChatColor.GOLD+" "+p.economy().price(d)+" CC");x.sendMessage(ChatColor.AQUA+"Balance: "+p.economy().getCoins(x)+" CC");return true;}if(a[0].equalsIgnoreCase("balance")){x.sendMessage(ChatColor.AQUA+"You have "+p.economy().getCoins(x)+" CC.");return true;}if(a[0].equalsIgnoreCase("buy")&&a.length>=2){CardDefinition d=p.cards().get(a[1]);p.economy().buy(x,d);return true;}return true;}public List<String>onTabComplete(CommandSender s,Command c,String l,String[]a){if(a.length==1)return Arrays.asList("list","balance","buy");if(a.length==2&&a[0].equalsIgnoreCase("buy")){List<String>r=new ArrayList<String>();if(s instanceof Player){Player p1=(Player)s;for(CardDefinition d:p.cards().all())if(d.cardClass.equalsIgnoreCase(p.profiles().getClass(p1))&&p.economy().price(d)>0)r.add(d.id);}return r;}return Collections.emptyList();}}
